    "أصناف تحت الحدّ",
    "أنت بلا اتصال الآن، وهذه الصفحة تحتاج الشبكة. إن كنت عميلاً فافتح تطبيقك — يبيع ويحفظ بلا إنترنت.",
    "أنت. تصدير كامل في أي وقت، وانتهاء الاشتراك لا يحجب دفترك — ما يُحجب وما لا يُحجب مكتوب في قسم الباقات أعلاه.",
    "أنشئ منشأتك",
