    "أيام",
    "ابحث بالاسم أو الباركود، بِع بالوحدة أو بالكرتونة، نقداً أو آجلاً أو تحويلاً. انقطع الاتصال؟ تُحفظ الفاتورة على الجهاز برقمها وتُرفع مرة واحدة عند عودة الشبكة.",
