    "التكلفة",
    "التكلفة ارتفعت بمستند",
    "التكلفة تتبع مستندات الشراء بالمتوسط المرجّح، وتتغيّر مع كل استلام. والهامش مشتقٌّ منها ومن سعر البيع — فمن يرى الهامش يرى التكلفة ضمناً، ولذلك صلاحيتهما واحدة.",
    "التكلفة والهامش",
