    "+ معلّق هذا الجهاز",
    ". حُسب في",
    ": بِيع أكثر مما دخل مسجَّلاً. السبب غالباً إدخال شراء لم يُسجَّل بعد. لا نصفّره ولا نمنع البيع بأثر رجعي — نعرضه حتى يُصحَّح بمستند.",
